style.css:
@-moz-document domain("syosetu.com") {
/* ============================================================
     Syosetu (Narou) Dark
     The Syosetu network shares one frontend across the portal
     (syosetu.com), the novel reader (ncode/novel18.syosetu.com),
     the ranking/search site (yomou.syosetu.com) and mypage. Colors
     are HARDCODED (no CSS custom properties), so this reskins per
     element. Priorities: a calm reading surface for long-form
     Japanese text (soft off-white body on a dark bg, never glare),
     opaque sticky reader header/menu, legible chapter nav and font
     /bookmark controls, and the signature Narou brown + ranking
     medal colors refined for dark. Layout/typography untouched —
     colors only.
     ============================================================ */

  :root {
    color-scheme: dark !important;
  }

  /* ---- Base surfaces ---- */
  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* Soften every default light border into a subtle dark divider */
  * {
    border-color: #262c33 !important;
  }

  /* Generic light wrappers / panels -> elevated dark surface */
  .l-container,
  .l-main,
  .l-wrap,
  .l-jumbotron,
  .c-panel,
  .c-panel__body,
  .c-announce-box,
  .c-announce,
  .c-document,
  .searchkekka_box,
  .searchForm_box,
  .search_box,
  .index_box,
  .novel_bn,
  .p-footer-nav,
  .c-novel-attention,
  #novel_color,
  #container,
  #contents_main,
  #wrap {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* Card surfaces (ranking cards, recommendations, bookmark bar,
     feedback form) -> elevated dark, opaque */
  .c-card,
  .p-ranktop-item,
  .p-recommend,
  .p-recommend__item,
  .p-bookmark-bar,
  .c-novel-feedback-form,
  .p-bookmark-modal,
  .c-modal,
  .c-modal__item {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     Header / global navigation
     ============================================================ */
  .p-header,
  .l-header,
  .c-menu,
  .c-menu__body {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }

  .p-header__logo,
  .p-header__description,
  .p-header__description-data,
  .p-header__count,
  .p-header__subnav-item,
  .p-header__subnav-item a {
    color: #c4cdd6 !important;
  }

  /* Signature Narou brown nav -> deep warm-brown bar that keeps the
     identity but sits on dark without glare */
  .p-main-nav,
  .p-sub-nav {
    background-color: #2a1a10 !important;
    border-color: #3a2517 !important;
  }

  .p-main-nav__item,
  .p-main-nav__item a,
  .p-main-nav__item-name,
  .p-sub-nav__item,
  .p-sub-nav__item a {
    color: #f0dccb !important;
  }

  .p-main-nav__item:hover,
  .p-main-nav__item a:hover {
    color: #ffffff !important;
  }

  /* "ユーザ登録" CTA pill (orange bg) — keep the brand orange but
     darken the label so it reads (was light-on-orange) */
  .p-main-nav__item--useradd,
  .p-main-nav__item--useradd .p-main-nav__item-name {
    color: #1a1109 !important;
  }

  /* Horizontal scroll-tab navs (ranking tabs, news/お知らせ tabs, genre
     sub-buttons) paint a "more →" scroll-fade via a ::after gradient that
     fades to WHITE — a bright strip at the right edge on dark. Remap the
     gradient stop to the page base so the fade reads dark. */
  .c-horizontalnav__mask::after,
  .c-horizontalnav-button__mask::after {
    background-image: linear-gradient(to left, #14181d, rgba(20, 24, 29, 0)) !important;
  }

  /* ============================================================
     Links & accents
     ============================================================ */
  a {
    color: #5fb0e6 !important;
  }
  a:hover {
    color: #9bd4ff !important;
  }

  /* Narou warm-orange link/title accent (search, novel titles):
     keep the orange identity, lift for dark legibility */
  .novel_h a,
  .noveltitle a,
  .c-novel-item__title a {
    color: #f0954a !important;
  }
  .novel_h a:hover,
  .noveltitle a:hover,
  .c-novel-item__title a:hover {
    color: #ffb877 !important;
  }

  /* Red menu accent (login / bookmark) -> refined warm red.
     The sticky header sits over the page, so keep its items opaque. */
  .c-menu__item,
  .c-menu__item--login,
  .c-menu__item--headnav,
  .c-menu__item--bookmark {
    background-color: #0d1117 !important;
    color: #ff7b72 !important;
  }
  .c-menu__item a {
    color: #ff7b72 !important;
  }

  /* ============================================================
     Reader — the novel chapter page (most important surface)
     Long-form Japanese text: soft off-white body, comfortable
     headings, dim-but-legible chapter metadata.
     ============================================================ */
  .p-novel,
  .p-novelmain,
  #novel_honbun,
  #novel_p,
  #novel_a {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* Body text — soft off-white, never pure white (reduces glare on
     long reading sessions). The chapter text is bare <p> elements
     inside .p-novel__text, each carrying the site's #444 — so target
     the paragraphs (and ruby furigana <rt>/<rp>) directly. */
  .p-novel__text,
  .js-novel-text,
  #novel_honbun,
  #novel_view,
  .novel_view,
  .p-novel__text p,
  .js-novel-text p,
  #novel_honbun p,
  #novel_view p,
  .novel_view p,
  .p-novel__text ruby,
  .p-novel__text rt,
  .p-novel__text rp,
  .js-novel-text rt,
  .js-novel-text rp {
    color: #c8d0d9 !important;
  }
  /* Furigana ruby annotations — slightly dimmer than the main line */
  .p-novel__text rt,
  .js-novel-text rt {
    color: #9aa3ad !important;
  }

  /* Chapter / story title */
  .p-novel__title,
  .p-novel__subtitle,
  .novel_subtitle,
  .c-title {
    color: #e6edf3 !important;
  }

  /* Episode number, dates, author line, update meta — muted but legible */
  .p-novel__number,
  .p-novel__author,
  .p-novel__date-published,
  .p-novel__date,
  .novel_writername,
  #novel_no,
  .koushinytime,
  .p-eplist__update,
  .c-pager__result-stats {
    color: #9aa3ad !important;
  }

  /* Story summary box */
  .p-novel__summary,
  #novel_ex {
    color: #b6c0ca !important;
  }

  /* Disclaimer/attention box — hardcoded #dd0000 red is harsh (~3.7:1)
     and illegible on dark; soften to the warm red that reads (≥4.5:1) */
  .c-novel-attention__warning {
    color: #ff7b72 !important;
  }

  /* New-impressions / reader comments block (bottom of chapter) —
     was #444 dark-on-dark */
  .p-new-impression,
  .p-new-impression__list,
  .p-new-impression__item {
    background-color: transparent !important;
  }
  .p-new-impression__headline,
  .p-new-impression__text,
  .p-new-impression__name {
    color: #c4cdd6 !important;
  }

  /* Reaction widget — the emoticon chips sit on a light #f1f3f5
     bar; darken it and lift the count text off link-blue */
  .p-reaction,
  .p-reaction__body,
  .js-reactionepisode_change,
  .p-reaction__emoticon {
    background-color: transparent !important;
  }
  .p-reaction__count {
    color: #9bd4ff !important;
  }

  /* ============================================================
     Novel comments / reviews (novelcom.syosetu.com)
     The 感想一覧 / レビュー一覧 and error pages use a newer component
     family (.p-novelcom-* / .c-postedtext-*) with hardcoded light
     fills: the empty-state + error message boxes ship #fafafa, the
     感想絞り込み filter button is a light #dee2e6 pill, and each posted
     impression carries a light-grey #adb6bf エピソード badge. Neutralize
     the boxes and darken the light chips (their labels stay light). */
  .c-postedtext--noposts,
  .p-novelcom-text,
  .p-novelcom-text--error {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  .p-novelcom-text__caution,
  .u-text-attention {
    color: #ff7b72 !important;
  }
  /* Light-grey control chips: the filter "全て表示" button and the per-
     comment エピソードN badge — dark elevated chip, keep the light label */
  .p-novelcom-header__narrowdown-button,
  .c-postedtext__target-info-episode {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* Posted impression/review meta (投稿者 line, dates) sits on transparent
     cards — keep it legible; poster-name links stay accent blue */
  .c-postedtext__poster,
  .c-postedtext__date,
  .c-postedtext__target-info {
    color: #9aa3ad !important;
  }
  .c-postedtext__poster a,
  .c-postedtext__target-info a {
    color: #5fb0e6 !important;
  }

  /* ============================================================
     Story index (TOC) — episode list
     ============================================================ */
  .p-eplist,
  .index_box {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  .p-eplist__chapter-title,
  .chapter_title {
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .p-eplist__sublist,
  .p-eplist__subtitle a,
  .subtitle a {
    color: #5fb0e6 !important;
  }
  .p-eplist__subtitle a:hover,
  .subtitle a:hover {
    color: #9bd4ff !important;
  }

  /* ============================================================
     Pager / chapter prev-next navigation
     ============================================================ */
  .c-pager,
  .c-pager__pager {
    background-color: transparent !important;
  }
  .c-pager__item,
  .c-pager__item a,
  .novel_bn a {
    color: #5fb0e6 !important;
    border-color: #2d333b !important;
  }
  .c-pager__item a:hover,
  .novel_bn a:hover {
    color: #9bd4ff !important;
  }

  /* ============================================================
     Sticky reader menu / layout-adjust (font-size) controls
     Must stay OPAQUE so chapter text never bleeds through.
     ============================================================ */
  .p-adjust-layout,
  .p-adjust-layout__controller,
  .p-adjust-layout__switch,
  .p-adjust-layout__list,
  .p-adjust-layout__list-item,
  .p-adjust-layout__bottom-close,
  .p-adjust-layout__illustration,
  .c-hover-nav,
  .c-hover-nav__list {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .p-adjust-layout__title,
  .p-adjust-layout__switch,
  .p-adjust-layout__switch span,
  .p-adjust-layout__bottom-close,
  .p-adjust-layout__controller span,
  .c-hover-nav__title {
    color: #c4cdd6 !important;
  }
  .p-adjust-layout__title {
    color: #e6edf3 !important;
  }
  /* The layout on/off switch chips carry their own light fill (incl.
     the inner <span> that renders the toggle label) */
  .js-adjust-layout-on,
  .js-adjust-layout-off,
  .p-adjust-layout__controller,
  .p-adjust-layout__switch span,
  .js-adjust-layout-on span,
  .js-adjust-layout-off span {
    background-color: #1c2128 !important;
  }

  /* Floating up/down navigater pills (↓ to bottom / ↑ page-top) —
     were blue text on a pale #ccdddd pill */
  .c-navigater,
  .c-navigater--tobottom,
  .c-navigater--totop {
    background-color: #1c2128 !important;
    color: #9bd4ff !important;
    border-color: #2d333b !important;
  }
  .c-navigater a {
    color: #9bd4ff !important;
  }

  /* Font-size / layout radio + checkbox labels */
  .c-form__radio-label,
  .c-form__checkbox-label {
    color: #c4cdd6 !important;
  }
  /* The reader's 配色/メニューバー controls (and the search filters) use
     appearance:none custom radios/checkboxes with a hardcoded #fff disc —
     they glare as bright white dots on the dark panel. Darken the control;
     the checked ::before keeps its accent-blue dot, so selection still reads. */
  .c-form__radio-input,
  .c-form__checkbox-input {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }

  /* Bookmark (しおり) button — incl. the disabled modifier which
     carries its own #fafafa fill */
  .c-bookmark-button,
  .c-bookmark-button--disabled,
  .c-bookmark-button.c-bookmark-button--disabled {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .c-bookmark-button.c-bookmark-button--disabled {
    color: #9aa3ad !important;
  }

  /* Modal action buttons / toast close (were blue on white/#ddd) */
  .c-button,
  .c-button--gray,
  .c-toast__close,
  .toaster_close {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Rating stars / point form */
  .p-novelpoint-form,
  .p-novelpoint-form__body {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  .c-novelpoint-star {
    color: #d6a44a !important;
  }
  .p-novelpoint-form__note {
    color: #9aa3ad !important;
  }
  /* Impression form note carries its own cream #fff9db fill — darken it
     and lift the text so it doesn't flash a bright band in the form */
  .c-novel-feedback-form__note {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }
  /* Rating-point form note link defaults to #0033cc (~2:1 on dark) — lift
     to the accent blue (the generic a{} rule is out-specified here) */
  .p-novelpoint-form__note a {
    color: #5fb0e6 !important;
  }

  /* ============================================================
     Page titles, rankings, sidebar links
     ============================================================ */
  .c-page-title,
  .c-page-title__text {
    color: #e6c9a8 !important;
  }
  .p-ranktop-nav,
  .p-ranktop-nav__category,
  .p-ranktop-nav__plate,
  .p-ranktop-nav__genreblock,
  .c-suplink {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  /* The genre-nav plate is a white card; give it an elevated dark
     surface so the genre links read on it */
  .p-ranktop-nav__plate {
    background-color: #1c2128 !important;
  }
  .p-ranktop-nav__smallgenre a,
  .p-ranktop-nav__smallgenrelist a {
    color: #5fb0e6 !important;
  }

  /* Bookmark modal labels / counters / errors (were dark #2b2e38) */
  .p-bookmark-modal__title,
  .p-bookmark-modal__col-label,
  .c-modal__item-message-error,
  .js-isnoticecnt {
    color: #c4cdd6 !important;
  }

  /* Panel / ranking section headings (were teal #0d6572 / brown
     #582b13 on white — dark-on-dark now). Warm amber keeps the
     Narou identity and reads clearly on dark. */
  .c-panel__headline,
  .p-ranking__type-title,
  .c-card-cluster-title,
  .p-ranktop-item__header,
  .p-ranktop-nav__biggenrename,
  .p-ranktop-nav__category-name {
    color: #e6c9a8 !important;
  }

  /* Default rank number (non-medal). Keep medals below distinct. */
  .c-rank-place__num {
    color: #b6c0ca !important;
  }

  /* Pickup/highlighted ranking row (short ranking) carries a translucent
     light wash (rgba(241,243,245,.5)) that turns into a grey block on
     dark — swap it for a subtle elevated surface so it still reads as a
     highlight, not a glare patch */
  .p-ranking__item--short2 {
    background-color: #1c2128 !important;
  }

  /* Ranking medals — preserve the gold/silver/bronze semantics */
  .c-rank-place--1,
  .c-rank-place--1 .c-rank-place__num {
    color: #e3b341 !important;
  }
  .c-rank-place--2,
  .c-rank-place--2 .c-rank-place__num {
    color: #c9d1d9 !important;
  }
  .c-rank-place--3,
  .c-rank-place--3 .c-rank-place__num {
    color: #cd7f47 !important;
  }

  /* Novel list items — title link warm orange, author/meta legible */
  .c-novel-item__name,
  .c-novel-item__rank,
  .c-novel-item__subinfo,
  .c-novel-item__info {
    color: #c4cdd6 !important;
  }
  .c-novel-item__title a {
    color: #f0954a !important;
  }
  .c-novel-item__title a:hover {
    color: #ffb877 !important;
  }

  /* Status markers (連載中 / 完結済) — keep meaning, refine tone */
  .np_status,
  .noveltype {
    color: #9aa3ad !important;
  }
  .noveltype_rensai,
  .is-rensai {
    color: #5fb0e6 !important;
  }
  .noveltype_kanketsu,
  .is-kanketsu {
    color: #3fb950 !important;
  }

  /* ============================================================
     Forms / inputs (search, filters, mypage, feedback)
     ============================================================ */
  .c-form__input-text,
  .c-form__textarea,
  .c-form__select,
  input[type="text"],
  input[type="search"],
  input[type="number"],
  input[type="email"],
  input[type="password"],
  textarea,
  select {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  ::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }
  :-ms-input-placeholder {
    color: #8b949e !important;
  }

  /* Buttons / submit / search button */
  .c-form__input-group-button,
  button,
  input[type="submit"],
  input[type="button"],
  .btn-add,
  .btn-search,
  .js-search_conditions_btn {
    background-color: #21262d !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .c-form__input-group-button:hover,
  button:hover,
  input[type="submit"]:hover {
    background-color: #2d333b !important;
  }

  /* Search builder legacy tables / labels / keyword tags. This older
     markup uses bare <th>/<span>/<label> at #333 inside white
     containers — neutralize the surfaces and lift the text. */
  .c-trad-contents,
  .sub_box,
  .select_word_content,
  .word_content,
  .tab_box,
  .keyword_box,
  .searchForm_table,
  .searchForm_table th,
  .searchForm_table td,
  .search_label,
  .search_description,
  .search_text,
  .checkbox_list,
  .checkbox_list li,
  .checkbox_list label,
  .checkbox_list span,
  .content-head_h4 {
    background-color: transparent !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  /* Legacy search-builder section headers (#eee th + content heads) */
  .searchForm_table th,
  .content-head_h4 {
    background-color: #1c2128 !important;
    color: #e6c9a8 !important;
  }
  /* Legacy search labels, option lists, symbols (#666 / #333) */
  .search_label_colon,
  .search_label_history,
  .search_label_conf,
  .type_re_start_symbol,
  .searchForm_box li,
  .searchForm_box label,
  .searchForm_box span,
  .searchForm_box option,
  .searchForm_box .description,
  .searchForm_box .text80,
  .searchForm_box .dc_search_label,
  .search-history_setting-title,
  .search-history_setting-description,
  .checkbox_list label span,
  .word_content li,
  .word_content label {
    color: #c4cdd6 !important;
  }
  /* Keyword-suggestion links / tabs in the legacy search builder */
  .pointer,
  .select.pointer,
  .tab_box a,
  .tab_box .pointer {
    color: #5fb0e6 !important;
  }

  /* Expanding search-builder panels (ジャンル選択 / 詳細条件設定) are white
     #fff wrappers — they framed the dark inner tables and left their
     lower checkbox sections (抽出条件 / 作品に含まれる要素 / 除外条件) and
     the bottom action buttons sitting on white. Neutralize the panels;
     the inner tables/labels are already themed light-on-dark. */
  #cross_genre_list,
  #detail_config_list,
  .detail_config_list {
    background-color: transparent !important;
  }
  /* With the panels darkened, the detail-config row labels (読了時間 /
     文字数 / 総合ポイント / 掲載日 …) — bare #333 in .conf_box / td — go
     dark-on-dark. Lift the panel body text; <th> section heads keep amber
     and links stay blue (both out-specify these). */
  #detail_config_list td,
  #detail_config_list .conf_box,
  #detail_config_list label,
  #detail_config_list span,
  #cross_genre_list td,
  #cross_genre_list label,
  #cross_genre_list span {
    color: #c4cdd6 !important;
  }
  /* The login-required note inside the builder is a near-white #f6f6f6
     band — darken it (its text is already the light body color) */
  #detail_config_list .description,
  .searchForm_box .description,
  span.description {
    background-color: #21262d !important;
  }
  /* The site-guide / 特殊検索 / ヘルプ sidebar links render as white #fff
     button-pills (an <a> background) — flash a column of white blocks on
     dark. Clear the fill; the blue link text stays. */
  .list_g a {
    background-color: transparent !important;
  }

  /* Search-history panel (履歴から検索 → 検索履歴) is a full white #fff box
     (.js-search_conditions_list.search-history) framing #333 notes and
     white action buttons. Neutralize the panel + sub-boxes and lift the
     copy; the dark section-title bars + blue links already read. */
  .search-history,
  .js-search_conditions_list,
  .search-history_setting {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  .search-history_setting-note,
  .search-history_setting-content,
  .search-history_setting-description {
    color: #c4cdd6 !important;
  }
  .search-history_setting-btn {
    background-color: #21262d !important;
    color: #5fb0e6 !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     Legacy search RESULTS list (yomou.syosetu.com/search.php)
     This page mixes the search-builder form above with an older
     results table whose rows carry hardcoded light-theme colors:
     the excerpt (.ex, #660033 maroon) and the row body/status cells
     + metadata (.marginleft, bare <td>/<b> at #333) — all dark-on-
     dark now. The result rows live in #trad / #main_search, so scope
     the lift there: body text to soft off-white, metadata to muted
     grey, counter <b> bright. */
  #trad,
  #main_search,
  #main_search td,
  #main_search dl,
  #main_search dd,
  #main_search dt,
  #main_search p,
  .searchkekka_box,
  .searchkekka_box td,
  .searchkekka_box .ex,
  .searchkekka_box .left,
  .searchkekka_box .right,
  .searchkekka_box .series_title,
  .searchkekka_box .novel_h,
  .ex {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  /* Per-result metadata lines (読了時間 / 評価人数 / 評価ポイント /
     文字数), status cell, paging row, series lead, result count and
     the search-time note — muted grey */
  #main_search .marginleft,
  #main_search .left,
  #main_search .pager,
  #main_search .series_search__lead,
  .marginleft,
  .series_search__lead,
  .series_search__lead-supplement,
  .attenstion2,
  .attention {
    color: #9aa3ad !important;
  }
  /* Result count + metadata counters are bare <b> at #333 — keep them
     bright so the figures stand out from their labels */
  #main_search b,
  #main_search .marginleft b,
  .marginleft b {
    color: #e6edf3 !important;
  }
  /* The searched keyword is a bare <span> at #333 in the results header
     ("〈keyword〉 検索結果： N作品") — invisible on dark. Lift to the warm
     amber so the keyword reads and stands out like a heading. */
  #main_search > span {
    color: #e6c9a8 !important;
  }
  /* Per-result attribute badge (挿絵あり "has illustration") is a bare
     <span> with an inline background:#d7e9ef pale-cyan pill + #333 text —
     a bright chip glaring on the dark result row (audit-blind: short +
     inline). Darken the pill and lift its label. */
  .searchkekka_box span[style*="d7e9ef"],
  #main_search span[style*="d7e9ef"] {
    background: #21262d !important;
    color: #c4cdd6 !important;
  }

  /* Special-search / site-guide section headings on the search page
     (#333 / #663300 on light) — warm amber, matching the page titles */
  .h2_search,
  .h2_help {
    color: #e6c9a8 !important;
  }
  /* Trad-form checkbox option labels (作品傾向 etc.) + sidebar links
     are bare label>span / <a> still at #333/#000 — lift to body text
     and accent blue respectively */
  #trad label span,
  #trad option {
    color: #c4cdd6 !important;
  }
  #trad a {
    color: #5fb0e6 !important;
  }

  /* ============================================================
     R18 group sites (noc / mnlt / mid .syosetu.com — ノクターン /
     ムーンライト / ミッドナイトノベルズ). These share an OLDER legacy
     frontend than the main portal: white #fff content boxes
     (.main_box / .in_box / .xtop-syuppan / .a_line_t), brown #663300
     section headlines and #333 / maroon list text. Neutralize the
     boxes and lift the legacy text so the R18 top/reader read on dark.
     ============================================================ */
  .main_box,
  .main2_box,
  .in_box,
  .in_box2,
  .in_box3,
  .news_in_box,
  .info_messagebox,
  .title_h2,
  .a_line_t,
  .list_p,
  .list_p li,
  .list_p a,
  .official-x,
  .official-x_body,
  .xtop-syuppan,
  .xtop-syuppan__body {
    background-color: transparent !important;
    background-image: none !important;
    color: #c4cdd6 !important;
  }
  /* The R18 top mixes more bare #333 legacy text: the in_box2 section
     sub-labels (【検索種別】 / 【人気キーワード】), the +作品検索+ form caption,
     the in_box genre spans and the official-X report body — lift them all */
  .in_box2,
  .in_box2 div,
  .in_box2 span,
  .in_box span,
  .in_box3 form div,
  .bottom_space,
  .official-x_body,
  .official-x_text {
    color: #c4cdd6 !important;
  }
  /* Published-book showcase titles are a near-invisible #0033cc dark blue —
     swap to the warm orange used for novel titles elsewhere */
  .xtop-syuppan__syoseki-title {
    color: #f0954a !important;
  }
  /* Legacy brown #663300 section headlines -> warm amber */
  .h2_news,
  .h2_tag,
  .h2_book,
  .official-x_headline,
  .xtop-syuppan__headline {
    color: #e6c9a8 !important;
  }
  /* Legacy list titles (#333) and maroon excerpts (#663333) */
  .list_p_title {
    color: #e6edf3 !important;
  }
  .list_p_ex {
    color: #b6c0ca !important;
  }

  /* ============================================================
     Tables (generic), toasts, announcements
     ============================================================ */
  table,
  th,
  td {
    background-color: transparent !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  th {
    background-color: #1c2128 !important;
  }

  .c-toast,
  .c-toast__box-right {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .c-announce,
  .c-announce--note,
  .c-announce__emphasis {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .c-announce a,
  .c-announce--note a,
  .help-link {
    color: #5fb0e6 !important;
  }

  /* Recommendation "NNNNN user" bookmark-count badge — was green text
     on a pale green pill; keep the green meaning on a dark chip */
  .p-recommend__info-item--bookmarked {
    background-color: #15291f !important;
    color: #56d364 !important;
  }

  /* ============================================================
     User / author page (mypage.syosetu.com)
     ============================================================ */
  /* The profile header ships a solid white banner — it hides the
     display name (already light) and its block/mute + tab links.
     Neutralize the banner so everything on it reads on dark. */
  .p-userheader,
  .p-userheader__body,
  .p-userheader__tab {
    background-color: transparent !important;
    border-color: #262c33 !important;
  }
  .p-userheader__username {
    color: #e6edf3 !important;
  }
  .p-userheader__username-info {
    color: #9aa3ad !important;
  }
  /* The generic c-link component (activity-report / series / bookmark
     titles) renders mid-to-dark blue (#1b8ef3 / #1864ab); the --lg size
     is dark-on-dark. Lift the whole component to the readable accent. */
  .c-link,
  .c-link--md,
  .c-link--lg {
    color: #5fb0e6 !important;
  }
  .c-link:hover,
  .c-link--md:hover,
  .c-link--lg:hover {
    color: #9bd4ff !important;
  }
  /* c-panel list rows highlight on hover with a translucent light wash
     (rgba(241,243,245,.5)) that turns into a grey glare block on dark —
     swap it for a subtle dark elevated hover. */
  .c-panel__list-item:hover {
    background-color: #1c2128 !important;
  }

  /* ============================================================
     Footer
     ============================================================ */
  .l-footer,
  .l-foot-contents,
  footer {
    background-color: #0d1117 !important;
    color: #b6c0ca !important;
    border-color: #262c33 !important;
  }
  /* The mypage/group footer (.p-footer) ships a brand TEAL nav band and a
     bright CYAN copyright bar (audit-blind: colored, not near-white) —
     neutralize both onto the footer dark so they don't glare. The portal
     footer carries the same cyan band as a standalone .p-copyright strip. */
  .p-footer__body,
  .p-footer__foot,
  .p-copyright {
    background-color: #0d1117 !important;
  }
  .p-footer__foot,
  .p-copyright {
    color: #9aa3ad !important;
  }
  .l-footer a,
  .l-foot-contents a,
  footer a,
  .p-footer a {
    color: #9bd4ff !important;
  }

  /* Footer ranking-tag block / its "cannot display" notice are bare #444
     dark-on-dark in the foot-contents — lift to muted grey */
  .p-rankingtag,
  .p-rankingtag__notice,
  .p-rankingtag__item {
    color: #9aa3ad !important;
  }

  /* SNS share buttons - keep brand fills but ensure text legible */
  .c-sns__button {
    color: #e6edf3 !important;
  }

  /* R18 age-confirmation interstitial (年齢確認, the noc/mnlt/mid gate):
     a bare #modal whose heading (#444/#333) and body copy (#000) are
     dark-on-dark and all but invisible. Lift headings to amber and copy
     to body text; the Enter / exit links stay blue. */
  #modal h1,
  #modal h2 {
    color: #e6c9a8 !important;
  }
  #modal,
  #modal p {
    color: #c4cdd6 !important;
  }

  /* Ad / PR slots: neutral dark so blank slots don't flash white */
  .c-ad,
  .c-ad__item-horizontal,
  .c-pr {
    background-color: transparent !important;
  }
}
